style.css:
/* Pink Petal Academy — Shawnigan MySchoolApp */

/* swap these colors here */
:root {
  --my-pink: #e9a8c4;
  --my-blush: #fce8f0;
  --my-light: #fff5f8;
  --my-lavender: #eee7fa;
  --my-text: #745365;
  --my-muted: #ad899c;
}

/* soft pink page background */
html,
body {
  background: var(--my-blush) !important;
  color: var(--my-text) !important;
}

/* softer text */
body {
  font-family: "Trebuchet MS", "Segoe UI", sans-serif !important;
}

/* dreamy selection color */
::selection {
  background: #f3c1d7 !important;
  color: #745365 !important;
}

/* pretty scrollbars */
::-webkit-scrollbar {
  width: 9px !important;
}

::-webkit-scrollbar-track {
  background: #fff0f5 !important;
}

::-webkit-scrollbar-thumb {
  background: #e9b5cb !important;
  border-radius: 20px !important;
}

/* soft links */
a {
  color: #cb80a5 !important;
}

/* gentle form elements */
input,
select,
textarea {
  background: #fff8fb !important;
  border: 1px solid #f0c8d9 !important;
  border-radius: 10px !important;
  color: var(--my-text) !important;
}
